import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Bare Metal Cloud VNC Console User Guide","description":"","frontmatter":{"title":"Bare Metal Cloud VNC Console User Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-vnc-console-user-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-vnc-console-user-guide.md","lastUpdated":1794309341000}'),a={name:"operations-knowledge-base/baremetal/bare-metal-cloud-vnc-console-user-guide.md"};function n(l,e,i,h,u,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document describes how to access and use the VNC (Virtual Network Computing) console through the Bare Metal Cloud Control Panel, including common use cases and available features.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-what-is-the-vnc-console" tabindex="-1">1. What is the VNC Console? <a class="header-anchor" href="#_1-what-is-the-vnc-console" aria-label="Permalink to &quot;1. What is the VNC Console?&quot;">​</a></h2><p>VNC (Virtual Network Computing) provides direct console access to your server.</p><p>Unlike SSH or Remote Desktop (RDP), VNC does not rely on the server&#39;s network services. Even if SSH or RDP is unavailable, you can usually still access and manage your server through the VNC console.</p><hr><h2 id="_2-when-should-you-use-vnc" tabindex="-1">2. When Should You Use VNC? <a class="header-anchor" href="#_2-when-should-you-use-vnc" aria-label="Permalink to &quot;2. When Should You Use VNC?&quot;">​</a></h2><p>It is recommended to use VNC in the following situations:</p><ul><li>SSH connection is unavailable (Linux)</li><li>Remote Desktop (RDP) connection is unavailable (Windows)</li><li>You have forgotten your server login password</li><li>You need to modify network configurations</li><li>You want to view the server boot process</li><li>The operating system fails to start normally</li><li>System maintenance or troubleshooting is required</li></ul><hr><h2 id="_3-how-to-open-the-vnc-console" tabindex="-1">3. How to Open the VNC Console <a class="header-anchor" href="#_3-how-to-open-the-vnc-console" aria-label="Permalink to &quot;3. How to Open the VNC Console&quot;">​</a></h2><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Log in to the Raksmart Client Portal.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Select the server you want to manage.</li><li>Open the <strong>Management</strong> page.</li><li>Click <strong>VNC</strong>.</li><li>A new browser window will open automatically, and the VNC console connection will be established.</li><li>Once connected, the server console will be displayed.</li><li>Log in using your server&#39;s operating system username and password.</li></ol><p><strong>Note:</strong></p><p>The VNC console uses your server&#39;s operating system credentials (for example, <strong>root</strong> for Linux or <strong>Administrator</strong> for Windows), not your Raksmart Client Portal account.</p><hr><h2 id="_4-vnc-console-features" tabindex="-1">4. VNC Console Features <a class="header-anchor" href="#_4-vnc-console-features" aria-label="Permalink to &quot;4. VNC Console Features&quot;">​</a></h2><p>The following functions are available in the upper-right corner of the VNC console.</p><h2 id="paste-password" tabindex="-1">Paste Password <a class="header-anchor" href="#paste-password" aria-label="Permalink to &quot;Paste Password&quot;">​</a></h2><p>Quickly paste a copied password into the server login screen.</p><p>Recommended when:</p><ul><li>The password is long or contains special characters.</li><li>You want to avoid typing errors.</li></ul><hr><h2 id="clipboard" tabindex="-1">Clipboard <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Clipboard&quot;">​</a></h2><p>The Clipboard feature allows you to copy and paste text between your local computer and the VNC console.</p><p>Common uses include:</p><ul><li>Copying commands to the server.</li><li>Copying text from the server.</li><li>Improving operational efficiency.</li></ul><p><strong>Note:</strong></p><p>The Clipboard feature supports text only and does not support file transfer.</p><hr><h2 id="send-ctrl-alt-del" tabindex="-1">Send Ctrl + Alt + Del <a class="header-anchor" href="#send-ctrl-alt-del" aria-label="Permalink to &quot;Send Ctrl + Alt + Del&quot;">​</a></h2><p>Sends the <strong>Ctrl + Alt + Del</strong> key combination to the server.</p><p>Common uses include:</p><ul><li>Accessing the Windows login screen.</li><li>Opening Windows Security options.</li><li>Unlocking a Windows session.</li><li>Logging in to Windows systems that require <strong>Ctrl + Alt + Del</strong>.</li></ul><hr><h2 id="_5-what-can-you-do-with-the-vnc-console" tabindex="-1">5. What Can You Do with the VNC Console? <a class="header-anchor" href="#_5-what-can-you-do-with-the-vnc-console" aria-label="Permalink to &quot;5. What Can You Do with the VNC Console?&quot;">​</a></h2><p>The VNC console allows you to perform most routine server management tasks, including:</p><ul><li>Log in to the server</li><li>Change the system password</li><li>Monitor the server boot process</li><li>Modify network configurations</li><li>Restart the server</li><li>Diagnose system issues</li><li>Perform system maintenance and troubleshooting</li></ul><p>For Linux servers, you can also:</p><ul><li>Enter Single User Mode</li><li>Repair system configurations</li><li>View boot logs</li></ul><hr><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-which-username-and-password-should-i-use-to-log-in-through-vnc" tabindex="-1">Q1: Which username and password should I use to log in through VNC? <a class="header-anchor" href="#q1-which-username-and-password-should-i-use-to-log-in-through-vnc" aria-label="Permalink to &quot;Q1: Which username and password should I use to log in through VNC?&quot;">​</a></h3><p>Use your server&#39;s operating system credentials.</p><p>For example:</p><ul><li>Linux: <strong>root</strong></li><li>Windows: <strong>Administrator</strong></li></ul><hr><h3 id="q2-why-can-i-access-the-server-through-vnc-but-not-through-ssh-or-rdp" tabindex="-1">Q2: Why can I access the server through VNC but not through SSH or RDP? <a class="header-anchor" href="#q2-why-can-i-access-the-server-through-vnc-but-not-through-ssh-or-rdp" aria-label="Permalink to &quot;Q2: Why can I access the server through VNC but not through SSH or RDP?&quot;">​</a></h3><p>SSH and RDP depend on the server&#39;s network configuration and related services.</p><p>VNC connects directly to the server console, so it usually remains available even if the network configuration is incorrect or the remote access services are not running.</p><hr><h3 id="q3-can-i-change-my-server-password-through-vnc" tabindex="-1">Q3: Can I change my server password through VNC? <a class="header-anchor" href="#q3-can-i-change-my-server-password-through-vnc" aria-label="Permalink to &quot;Q3: Can I change my server password through VNC?&quot;">​</a></h3><p>Yes.</p><p>After logging in to the operating system through VNC, you can change your password using the standard operating system method.</p><p>If you have forgotten your password, you can also use the <strong>Reset Password</strong> feature in the control panel.</p><p>For more information, please refer to the <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.html"><strong>Bare Metal Cloud Password Change and Reset Guide</strong>.</a></p><hr><h3 id="q4-can-i-transfer-files-through-the-vnc-console" tabindex="-1">Q4: Can I transfer files through the VNC console? <a class="header-anchor" href="#q4-can-i-transfer-files-through-the-vnc-console" aria-label="Permalink to &quot;Q4: Can I transfer files through the VNC console?&quot;">​</a></h3><p>No.</p><p>The <strong>Clipboard</strong> feature supports text copy and paste only. It does not support file transfers.</p><p>To transfer files, we recommend using:</p><ul><li><strong>Linux:</strong> SCP or SFTP</li><li><strong>Windows:</strong> Remote Desktop file sharing, FTP, or other file transfer tools</li></ul><hr><h3 id="q5-will-closing-the-vnc-browser-window-affect-my-server" tabindex="-1">Q5: Will closing the VNC browser window affect my server? <a class="header-anchor" href="#q5-will-closing-the-vnc-browser-window-affect-my-server" aria-label="Permalink to &quot;Q5: Will closing the VNC browser window affect my server?&quot;">​</a></h3><p>No.</p><p>Closing the VNC window only disconnects the current console session. It does not affect the operation of your server.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ The VNC console uses your server&#39;s operating system credentials, not your Raksmart Client Portal account.</p><p>⚠️ VNC is recommended as an emergency access method when SSH or RDP is unavailable. For routine server management, SSH (Linux) or Remote Desktop (Windows) is still recommended.</p><p>⚠️ The Clipboard feature supports text only and does not support file transfers.</p><p>⚠️ Before making major system changes, it is recommended to back up your important data.</p><hr>',75)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
